/**
 * Generates `yoga.wasm`, `src/yoga-glue.ts` and `src/yoga-enums.ts` from the
 * installed `yoga-layout` package.
 *
 *   bun packages/core/scripts/gen-yoga-wasm.ts [--check]
 *
 * `yoga-layout/load` inlines its WebAssembly as a base64 `data:` URL inside
 * the Emscripten loader. This splits the binary out into `yoga.wasm` (served
 * as an asset, imported as a module on Workers) and keeps the loader without
 * the string or its base64 decoder. `--check` fails if any output is stale.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";

const PKG = join(import.meta.dir, "..");

export interface YogaArtifacts {
  version: string;
  wasm: Uint8Array;
  glue: string;
  enums: string;
}

/** Replace `find` (which must occur exactly once) with `replace`. */
function replaceOnce(source: string, find: string | RegExp, replace: string, what: string): string {
  const pattern = typeof find === "string" ? new RegExp(find.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "g") : new RegExp(find.source, "g");
  const count = source.match(pattern)?.length ?? 0;
  if (count !== 1) throw new Error(`gen-yoga-wasm: expected one ${what} in yoga-layout's loader, found ${count}. Update this script for the new yoga-layout.`);
  return source.replace(pattern, () => replace);
}

export function generateYoga(): YogaArtifacts {
  const require = createRequire(join(PKG, "package.json"));
  const root = dirname(require.resolve("yoga-layout/package.json"));
  const version = (JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as { version: string }).version;
  const header = `// Generated by scripts/gen-yoga-wasm.ts from yoga-layout ${version}. Do not edit.
// yoga-layout © Meta Platforms, Inc. and affiliates, MIT license (https://github.com/facebook/yoga/blob/main/LICENSE).`;

  let loader = readFileSync(join(root, "dist/binaries/yoga-wasm-base64-esm.js"), "utf8");
  const data = /H="data:application\/octet-stream;base64,([A-Za-z0-9+/=]+)"/.exec(loader);
  if (!data?.[1]) throw new Error("gen-yoga-wasm: yoga-layout's loader has no inlined WebAssembly. Update this script for the new yoga-layout.");
  const wasm = new Uint8Array(Buffer.from(data[1], "base64"));
  loader = replaceOnce(loader, data[0], 'H=""', "inlined WebAssembly");
  loader = replaceOnce(loader, /var xa="function"==typeof atob\?atob:function\(a\)\{[\s\S]*?return b\},Jb=/, "var xa=null,Jb=", "base64 decoder");
  loader = replaceOnce(loader, "var _scriptDir = import.meta.url;", 'var _scriptDir = "";', "script URL");
  loader = replaceOnce(loader, "var loadYoga = (() => {", "var loadYoga = /*#__PURE__*/ (() => {", "loader factory");
  loader = replaceOnce(loader, "export default loadYoga;", "", "default export").trim();

  let wrap = readFileSync(join(root, "dist/src/wrapAssembly.js"), "utf8");
  wrap = wrap.replace(/^\/\*\*[\s\S]*?\*\/\s*/, "").replace(/^\/\/ @ts-nocheck\s*/m, "").replace(/^import .*;\n/gm, "").replace(/^\/\/# sourceMappingURL=.*$/m, "");
  wrap = replaceOnce(wrap, "export default function wrapAssembly(lib)", "function wrapAssembly(lib)", "wrapAssembly export").trim();

  const glue = `// @ts-nocheck
${header}
//
// Yoga's Emscripten loader without the base64 copy of its WebAssembly (which ships as
// \`yoga.wasm\`), and yoga-layout's \`wrapAssembly\`. See yoga-wasm.ts.

import type { Yoga } from "yoga-layout/load";
import YGEnums, { Direction, Unit } from "./yoga-enums";

${loader}

${wrap}

/**
 * Run Yoga's loader, with \`instantiate\` turning the loader's imports into a WebAssembly instance.
 * Rejects on any failure, including an instance that isn't Yoga's (the loader would wait forever).
 */
export function createYoga(instantiate: (imports: WebAssembly.Imports) => Promise<WebAssembly.Instance>): Promise<Yoga> {
  return new Promise((resolve, reject) => {
    loadYoga({
      instantiateWasm(imports, receiveInstance) {
        instantiate(imports)
          .then((instance) => receiveInstance(instance))
          .catch(reject);
        return {};
      },
    })
      .then((lib) => resolve(wrapAssembly(lib)))
      .catch(reject);
  });
}
`;

  let enums = readFileSync(join(root, "dist/src/generated/YGEnums.js"), "utf8");
  enums = enums.replace(/^\/\*\*[\s\S]*?\*\/\s*/, "").replace(/^\/\/ @generated.*\n\s*/m, "").replace(/^\/\/# sourceMappingURL=.*$/m, "");
  const names: string[] = [];
  enums = enums.replace(/^export let (\w+) = /gm, (_m, name: string) => {
    names.push(name);
    return `export type ${name} = Y.${name};\nexport const ${name}: typeof Y.${name} = `;
  });
  if (names.length === 0) throw new Error("gen-yoga-wasm: yoga-layout's YGEnums.js has no enums. Update this script for the new yoga-layout.");
  const enumsOut = `// @ts-nocheck
${header}
//
// Yoga's enums, typed as yoga-layout's own, so the browser build never imports \`yoga-layout/load\`.

import type * as Y from "yoga-layout/load";

${enums.trim()}
`;
  return { version, wasm, glue, enums: enumsOut };
}

export const OUTPUTS = { wasm: join(PKG, "yoga.wasm"), glue: join(PKG, "src/yoga-glue.ts"), enums: join(PKG, "src/yoga-enums.ts") } as const;

if (import.meta.main) {
  const out = generateYoga();
  if (process.argv.includes("--check")) {
    const stale = [
      Buffer.compare(Buffer.from(out.wasm), readFileSync(OUTPUTS.wasm)) !== 0 ? "yoga.wasm" : null,
      out.glue !== readFileSync(OUTPUTS.glue, "utf8") ? "src/yoga-glue.ts" : null,
      out.enums !== readFileSync(OUTPUTS.enums, "utf8") ? "src/yoga-enums.ts" : null,
    ].filter(Boolean);
    if (stale.length > 0) {
      console.error(`Stale: ${stale.join(", ")}. Run bun packages/core/scripts/gen-yoga-wasm.ts`);
      process.exit(1);
    }
  } else {
    writeFileSync(OUTPUTS.wasm, out.wasm);
    writeFileSync(OUTPUTS.glue, out.glue);
    writeFileSync(OUTPUTS.enums, out.enums);
    console.log(`yoga-layout ${out.version}: yoga.wasm ${out.wasm.length} B, yoga-glue.ts ${out.glue.length} B, yoga-enums.ts ${out.enums.length} B`);
  }
}
